function legacyx_theme_setup(){add_theme_support('title-tag');add_theme_support('post-thumbnails');add_theme_support('html5',array('search-form','comment-form','comment-list','gallery','caption','style','script'));register_nav_menus(array('primary'=>__('Primary Navigation','legacy-x-firm')));}add_action('after_setup_theme','legacyx_theme_setup');
function legacyx_enqueue_assets(){$css=get_stylesheet_directory().'/style.css';$polish=get_stylesheet_directory().'/assets/css/polish.css';$assessment=get_stylesheet_directory().'/assets/css/assessment.css';$workflow=get_stylesheet_directory().'/assets/css/workflow.css';wp_enqueue_style('legacyx-style',get_stylesheet_uri(),array(),file_exists($css)?filemtime($css):'1');wp_enqueue_style('legacyx-polish',get_stylesheet_directory_uri().'/assets/css/polish.css',array('legacyx-style'),file_exists($polish)?filemtime($polish):'1');if(is_page('executive-assessment'))wp_enqueue_style('legacyx-assessment',get_stylesheet_directory_uri().'/assets/css/assessment.css',array('legacyx-polish'),file_exists($assessment)?filemtime($assessment):'1');if(is_page('documents-tasks'))wp_enqueue_style('legacyx-workflow',get_stylesheet_directory_uri().'/assets/css/workflow.css',array('legacyx-polish'),file_exists($workflow)?filemtime($workflow):'1');}add_action('wp_enqueue_scripts','legacyx_enqueue_assets');
function legacyx_client_portal_template($t){if(get_query_var('legacyx_application_id')){$f=get_theme_file_path('/application-detail.php');if(file_exists($f))return $f;}$map=array('client-portal'=>'client-portal.php','executive-assessment'=>'executive-assessment.php','credit-capital-center'=>'credit-capital-center.php','business-center'=>'business-center.php','documents-tasks'=>'documents-tasks.php','applications-center'=>'applications-center.php','billing-payments'=>'billing-payments.php','my-services'=>'my-services.php','appointments-messages'=>'appointments-messages.php');foreach($map as $slug=>$file)if(is_page($slug)){ $f=get_theme_file_path('/'.$file);if(file_exists($f))return $f;}return $t;}add_filter('template_include','legacyx_client_portal_template',99);
function legacyx_application_routes(){add_rewrite_rule('^applications-center/application/([0-9]+)/?$','index.php?legacyx_application_id=$matches[1]','top');}add_action('init','legacyx_application_routes',9);function legacyx_application_query_vars($vars){$vars[]='legacyx_application_id';return $vars;}add_filter('query_vars','legacyx_application_query_vars');
function legacyx_body_classes($c){foreach(array('client-portal','executive-assessment','credit-capital-center','business-center','documents-tasks','applications-center','billing-payments','my-services','appointments-messages') as $slug)if(is_page($slug))$c[]='legacyx-'.$slug.'-page';if(get_query_var('legacyx_application_id'))$c[]='legacyx-application-detail-page';return $c;}add_filter('body_class','legacyx_body_classes');
function legacyx_ensure_system_pages(){foreach(array('executive-assessment'=>'Executive Assessment','credit-capital-center'=>'Credit & Capital Center','business-center'=>'Business Center','documents-tasks'=>'Documents & Tasks','applications-center'=>'Applications Center','billing-payments'=>'Billing & Payments','my-services'=>'My Services','appointments-messages'=>'Appointments & Messages') as $slug=>$title)if(!get_page_by_path($slug))wp_insert_post(array('post_title'=>$title,'post_name'=>$slug,'post_status'=>'publish','post_type'=>'page','post_content'=>''));}add_action('init','legacyx_ensure_system_pages',20);
function legacyx_flush_application_routes_once(){if(get_option('legacyx_application_routes_v1')!=='1'){flush_rewrite_rules(false);update_option('legacyx_application_routes_v1','1');}}add_action('init','legacyx_flush_application_routes_once',30);
function legacyx_register_assessment_type(){register_post_type('legacyx_assessment',array('labels'=>array('name'=>'Executive Assessments','singular_name'=>'Executive Assessment','menu_name'=>'Assessments'),'public'=>false,'show_ui'=>true,'show_in_menu'=>true,'menu_icon'=>'dashicons-clipboard','supports'=>array('title'),'capability_type'=>'post','map_meta_cap'=>true));}add_action('init','legacyx_register_assessment_type');
function legacyx_clean_assessment_array($v){return is_array($v)?array_values(array_filter(array_map('sanitize_text_field',$v))):array();}
function legacyx_submit_assessment(){if(!isset($_POST['legacyx_assessment_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['legacyx_assessment_nonce'])),'legacyx_assessment_submit'))wp_die('Security validation failed.','Legacy X Firm',array('response'=>403));$n=sanitize_text_field(wp_unslash($_POST['full_name']??''));$e=sanitize_email(wp_unslash($_POST['email']??''));$t=sanitize_text_field(wp_unslash($_POST['timeline']??''));$o=sanitize_textarea_field(wp_unslash($_POST['objective']??''));if(!$n||!is_email($e)||!$t||!$o||empty($_POST['consent']))wp_die('Please complete all required assessment fields.','Legacy X Firm',array('response'=>400));$aid=wp_insert_post(array('post_type'=>'legacyx_assessment','post_status'=>'private','post_title'=>$n.' — '.current_time('Y-m-d H:i')));if(!$aid||is_wp_error($aid))wp_die('We could not save your assessment.');$f=array('full_name'=>$n,'email'=>$e,'phone'=>sanitize_text_field(wp_unslash($_POST['phone']??'')),'location'=>sanitize_text_field(wp_unslash($_POST['location']??'')),'role'=>sanitize_text_field(wp_unslash($_POST['role']??'')),'business_name'=>sanitize_text_field(wp_unslash($_POST['business_name']??'')),'business_stage'=>sanitize_text_field(wp_unslash($_POST['business_stage']??'')),'revenue'=>sanitize_text_field(wp_unslash($_POST['revenue']??'')),'capital_need'=>sanitize_text_field(wp_unslash($_POST['capital_need']??'')),'timeline'=>$t,'objective'=>$o,'obstacle'=>sanitize_textarea_field(wp_unslash($_POST['obstacle']??'')),'engagement'=>sanitize_text_field(wp_unslash($_POST['engagement']??'')),'source'=>sanitize_text_field(wp_unslash($_POST['source']??'')),'priorities'=>legacyx_clean_assessment_array(isset($_POST['priorities'])?wp_unslash($_POST['priorities']):array()),'submitted_at'=>current_time('mysql'));foreach($f as $k=>$v)update_post_meta($aid,'_legacyx_'.$k,$v);$p=preg_split('/\s+/',trim($n),2);$cid=wp_insert_post(array('post_type'=>'legacyx_client','post_status'=>'publish','post_title'=>$n.($f['business_name']?' — '.$f['business_name']:'')));if($cid&&!is_wp_error($cid)){$m=array('first_name'=>$p[0]??'','last_name'=>$p[1]??'','email'=>$e,'phone'=>$f['phone'],'business_name'=>$f['business_name'],'annual_revenue'=>$f['revenue'],'capital_goal'=>$f['capital_need'],'status'=>'Assessment','service_level'=>$f['engagement'],'source'=>$f['source']?:'Executive Assessment','assessment_id'=>$aid,'ownership_notes'=>'Primary role: '.$f['role']."\nBusiness stage: ".$f['business_stage'],'financial_notes'=>'Primary objective: '.$o."\nCurrent obstacle: ".$f['obstacle']."\nTimeline: ".$t."\nPriorities: ".implode(', ',$f['priorities']));foreach($m as $k=>$v)update_post_meta($cid,'_legacyx_'.$k,$v);update_post_meta($cid,'_legacyx_client_id',legacyx_client_id($cid));update_post_meta($aid,'_legacyx_client_profile_id',$cid);}wp_mail(get_option('admin_email'),'New Legacy X Firm Executive Assessment — '.$n,"New Executive Assessment submitted.\nName: {$n}\nEmail: {$e}\nTimeline: {$t}");wp_safe_redirect(add_query_arg('submitted','1',home_url('/executive-assessment/')));exit;}add_action('admin_post_nopriv_legacyx_submit_assessment','legacyx_submit_assessment');add_action('admin_post_legacyx_submit_assessment','legacyx_submit_assessment');
function legacyx_assessment_details_box(){add_meta_box('legacyx-assessment-details','Executive Assessment Details','legacyx_render_assessment_details','legacyx_assessment','normal','high');}add_action('add_meta_boxes','legacyx_assessment_details_box');function legacyx_render_assessment_details($post){foreach(array('full_name'=>'Full Name','email'=>'Email','business_name'=>'Business','timeline'=>'Timeline','objective'=>'Primary Outcome','obstacle'=>'Current Obstacle','priorities'=>'Strategic Priorities') as $k=>$l){$v=get_post_meta($post->ID,'_legacyx_'.$k,true);if(is_array($v))$v=implode(', ',$v);echo '<p><strong>'.esc_html($l).':</strong><br>'.nl2br(esc_html($v)).'</p>';}}
function legacyx_disable_emojis(){remove_action('wp_head','print_emoji_detection_script',7);remove_action('wp_print_styles','print_emoji_styles');}add_action('init','legacyx_disable_emojis');remove_action('wp_head','rsd_link');remove_action('wp_head','wlwmanifest_link');remove_action('wp_head','wp_generator');remove_action('wp_head','wp_oembed_add_discovery_links');function legacyx_remove_dashicons(){if(!is_user_logged_in())wp_dequeue_style('dashicons');}add_action('wp_enqueue_scripts','legacyx_remove_dashicons',100);
